const MINX = 68.491806, MAXY = 38.0186832542101, SC = 27.659308541488357, OX = 0, OY = 17.840880014460993;

/** Project a lon/lat pair into the same SVG viewBox as the state paths. */
export function projectIndia(lon: number, lat: number): [number, number] {
  const y = (Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI / 180) / 2)) * 180) / Math.PI;
  return [(lon - MINX) * SC + OX, (MAXY - y) * SC + OY];
}
